def linearBasisRankAndMax(nums: list[int]) -> list[int]:
    basis = [0] * 32
    rank = 0
    for x in nums:
        for b in range(31, -1, -1):
            if (x >> b) & 1:
                if not basis[b]:
                    basis[b] = x
                    rank += 1
                    break
                x ^= basis[b]
    max_xor = 0
    for b in range(31, -1, -1):
        if (max_xor ^ basis[b]) > max_xor:
            max_xor ^= basis[b]
    return [rank, max_xor]

